    'd.givefeedback.a': "Ordentlich! Nur die Kartons stehen schief.", // nieuw, nalezen
    'l.meeting': "In der Teambesprechung etwas sagen", // nieuw, nalezen
    'w.werkoverleg': "die Teambesprechung (über die Arbeit)", // nieuw, nalezen
